import{spawn}from"node:child_process";var[command,...args]=process.argv.slice(2);if(!command)throw new Error("Code command missing");var child=spawn(command,args,{detached:!0,stdio:["ignore","inherit","inherit"],env:process.env}),stopping=!1,finished=!1,code=null;function signalGroup(signal){if(child.pid)try{process.kill(-child.pid,signal)}catch(error){if(error.code!=="ESRCH")throw error}}function stop(){stopping||(stopping=!0,signalGroup("SIGTERM"),setTimeout(()=>{signalGroup("SIGKILL"),finished&&process.exit(code??1)},500),setTimeout(()=>process.exit(code??1),1500))}child.once("error",error=>{console.error(error.message),finished=!0,code=127,stop()});child.once("exit",value=>{finished=!0,code=value,stop()});process.once("disconnect",stop);process.once("SIGTERM",stop);process.once("SIGINT",stop);
